contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable {
        require(target != address(c));
        require(amount <= address(c).balance);
        uint cBalanceBefore = address(c).balance;
        uint targetBalanceBefore = target.balance;
        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;
        assert(address(c).balance == cBalanceBefore - amount && target.balance == targetBalanceBefore + amount);
    }

    receive() external payable {}
}

